import{_ as s,o as t,c as e,a3 as o}from"./chunks/framework.DsQ8uxR7.js";const i="/oss/konado/assets/reimport.BKYRtpO_.png",m=JSON.parse('{"title":"Konado 脚本","description":"","frontmatter":{"title":"Konado 脚本","order":1},"headers":[],"relativePath":"zh/tutorial/script/konado-script.md","filePath":"zh/tutorial/script/konado-script.md","lastUpdated":1778242448000}'),n={name:"zh/tutorial/script/konado-script.md"};function r(p,a,l,c,d,h){return t(),e("div",null,[...a[0]||(a[0]=[o(`<h1 id="konado-scripts" tabindex="-1">Konado Scripts <a class="header-anchor" href="#konado-scripts" aria-label="Permalink to &quot;Konado Scripts&quot;">​</a></h1><p>Konado Scripts 是一种为视觉小说量身定制的创作语言（文件后缀为 .ks）。</p><p>你可以把它想象成一种更强大、更结构化的“小说剧本”：开发者无需编写复杂代码，就能控制剧情对话、角色立绘、背景切换、音乐音效，以及故事分支和选项。</p><h2 id="设计理念" tabindex="-1">设计理念 <a class="header-anchor" href="#设计理念" aria-label="Permalink to &quot;设计理念&quot;">​</a></h2><p>Konado Script 的核心设计理念是将<strong>故事内容</strong>与<strong>程序逻辑</strong>分离：</p><ul><li>编剧专注于叙事内容，无需编程知识</li><li>程序员专注于引擎开发，无需介入故事创作</li><li>资源管理（图片、音频）通过标识符引用，与脚本解耦</li><li>模块化指令集，易于扩展新功能</li><li>兼容版本控制系统（Git等）</li><li>文本格式天生跨平台</li><li>资源引用与平台无关</li></ul><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><h3 id="_1-解析失败后保存无法触发重新解析" tabindex="-1">1. 解析失败后保存无法触发重新解析 <a class="header-anchor" href="#_1-解析失败后保存无法触发重新解析" aria-label="Permalink to &quot;1. 解析失败后保存无法触发重新解析&quot;">​</a></h3><p>控制台会提示错误信息，但保存后不会自动重新解析，这个是由于未成功触发重新导入导致的。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第5行内容：a1ctor show 可娜 正常 at 2 5 scale 0.3</span></span>
<span class="line"><span>  ERROR: core/variant/variant_utility.cpp:1024 - 错误：res://sample/demo/demo_01.ks [行：5] 解析失败：无法识别的语法，终止解析: a1ctor show 可娜 正常 at 2 5 scale 0.3 </span></span>
<span class="line"><span>  ERROR: Failed to process scripts</span></span>
<span class="line"><span>  ERROR: Error importing &#39;res://sample/demo/demo_01.ks&#39;.</span></span>
<span class="line"><span>  ERROR: Failed loading resource: res://sample/demo/demo_01.ks.</span></span></code></pre></div><p>找到对应的脚本文件，右键选择重新导入即可。</p><p><img src="`+i+'" alt="重新导入脚本"></p><h3 id="_2-脚本文件编码问题" tabindex="-1">2. 脚本文件编码问题 <a class="header-anchor" href="#_2-脚本文件编码问题" aria-label="Permalink to &quot;2. 脚本文件编码问题&quot;">​</a></h3><p>确保脚本文件编码为UTF-8，否则可能出现乱码，默认情况下创建的脚本文件编码为UTF-8。</p>',14)])])}const u=s(n,[["render",r]]);export{m as __pageData,u as default};
